CREATE TABLE "public"."leaves" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."leaves_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "leave_id" text,
  "employee_id" text,
  "full_name" text,
  "designation" text,
  "project_name" text,
  "leave_type" text,
  "from_date" text,
  "to_date" text,
  "days_count" integer,
  "reason" text,
  "status" text DEFAULT 'Pending'::text,
  "applied_on" text,
  "approved_by" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "employee_sys_id" bigint,
  "deleted_at" timestamp with time zone,
  "deleted_by" uuid,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."leaves" OWNER TO "postgres";
